//! The Rust mapping must produce exactly what the TypeScript mapping in cdr-toolchain produces.
//!
//! tests/fixtures/*.json are generated by tests/generate-fixtures.mts, which runs that TypeScript
//! over made-up v1 rows. Each file holds the rows the import host would send (`input`) and the
//! FHIR resources the TypeScript built from them (`expected`).
//!
//! Layer proven here: the mapping, natively. Not proven: the wasm build, and the host around it.

use serde_json::Value;
use std::fs;
use std::path::PathBuf;

fn fixtures() -> Vec<(String, Value)> {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests").join("fixtures");
    let mut out = Vec::new();
    for entry in fs::read_dir(&dir).expect("tests/fixtures exists") {
        let path = entry.unwrap().path();
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let name = path.file_stem().unwrap().to_string_lossy().to_string();
        let value: Value = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
        out.push((name, value));
    }
    out.sort_by(|a, b| a.0.cmp(&b.0));
    out
}

/// First difference between two JSON values, as a path. Numbers compare by value (40 == 40.0)
/// and object key order does not matter; array order does.
fn diff(path: &str, expected: &Value, actual: &Value) -> Option<String> {
    match (expected, actual) {
        (Value::Number(a), Value::Number(b)) => {
            if a.as_f64() == b.as_f64() {
                None
            } else {
                Some(format!("{path}: expected {a}, got {b}"))
            }
        }
        (Value::Object(a), Value::Object(b)) => {
            for (k, v) in a {
                match b.get(k) {
                    None => return Some(format!("{path}.{k}: missing, expected {v}")),
                    Some(w) => {
                        if let Some(d) = diff(&format!("{path}.{k}"), v, w) {
                            return Some(d);
                        }
                    }
                }
            }
            for (k, w) in b {
                if !a.contains_key(k) {
                    return Some(format!("{path}.{k}: unexpected {w}"));
                }
            }
            None
        }
        (Value::Array(a), Value::Array(b)) => {
            if a.len() != b.len() {
                return Some(format!("{path}: expected {} items, got {}", a.len(), b.len()));
            }
            for (i, (v, w)) in a.iter().zip(b).enumerate() {
                if let Some(d) = diff(&format!("{path}[{i}]"), v, w) {
                    return Some(d);
                }
            }
            None
        }
        (a, b) => {
            if a == b {
                None
            } else {
                Some(format!("{path}: expected {a}, got {b}"))
            }
        }
    }
}

#[test]
fn mapping_matches_the_typescript_for_every_fixture() {
    let mut cases = 0;
    let mut requests = 0;
    let mut failures = Vec::new();
    for (name, fixture) in fixtures() {
        if name == "attribute-rules" {
            continue;
        }
        cases += 1;
        let actual = openldr_v1_import::import_map(&fixture["input"]).unwrap_or_else(|e| panic!("{name}: import_map failed: {e}"));
        let expected_groups = fixture["expected"]["groups"].as_array().unwrap();
        let actual_groups = actual["groups"].as_array().unwrap();
        assert_eq!(expected_groups.len(), actual_groups.len(), "{name}: group count");
        for (e, a) in expected_groups.iter().zip(actual_groups) {
            requests += 1;
            let key = e["key"].as_str().unwrap();
            // A failed group has an `error` code and no resources. A good one has no `error` key.
            if let Some(d) = diff(&format!("{name}/{key}"), e, a) {
                failures.push(d);
            }
        }
    }
    assert!(cases >= 10, "expected at least 10 fixture cases, found {cases}");
    assert!(requests >= 31, "expected at least 31 requests, found {requests}");
    assert!(failures.is_empty(), "{} of {} requests differ:\n{}", failures.len(), requests, failures.join("\n"));
}

#[test]
fn attribute_rules_match_the_yaml_they_were_copied_from() {
    let (_, fixture) = fixtures().into_iter().find(|(n, _)| n == "attribute-rules").expect("attribute-rules.json");
    let expected: Vec<(String, String, String)> = fixture["rules"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| {
            (
                r["column"].as_str().unwrap().to_string(),
                r["code"].as_str().unwrap().to_string(),
                r["kind"].as_str().unwrap().to_string(),
            )
        })
        .collect();
    let actual: Vec<(String, String, String)> = openldr_v1_import::rules::RULES
        .iter()
        .map(|r| (r.column.to_string(), r.code.to_string(), r.kind.name().to_string()))
        .collect();
    assert_eq!(expected, actual);
}
